INSERT INTO "email_notifications" ("id","conversation_id","client_id","type","recipient_email","subject","custom_message","status","provider_message_id","error_message","created_at","sent_at") VALUES('79f94b85-603c-4627-b862-3b4e86ca7775','16dbfbe8-43cb-4611-9da4-076210d96fcc','9047f95b-b464-49b8-8e47-57c88857ba02','welcome','precious@leakendia.com','Welcome to Leakendia. Your investigation starts here.',NULL,'sent','01a1b7e3-c798-7a69-8d97-8cf9d6a5cf62',NULL,'2026-11-07 21:22:00','2026-11-07 21:22:00');
INSERT INTO "email_notifications" ("id","conversation_id","client_id","type","recipient_email","subject","custom_message","status","provider_message_id","error_message","created_at","sent_at") VALUES('b1f7728b-ace5-4d71-9fb6-f98f35f79316','16dbfbe8-43cb-4611-9da4-076210d96fcc','9047f95b-b464-49b8-8e47-57c88857ba02','custom','precious@leakendia.com','hey, how far',replace('Hi Dom,You might not have noticed this yet, but something important just shifted.A lot of product discovery isn’t happening on Google anymore.It’s happening inside AI tools.People are asking things like:\n“How do I cook perfect jollof rice?”\n“What spice mix should I use?”And instead of showing websites…AI tools choose which brands to mention.Right now, most stores aren’t positioned for this at all.Which means early movers are quietly taking that visibility.I’ve been helping a few brands set this up properly.From what I saw on your store, there’s a clear opportunity here.Curious if you’ve looked into this yet.','\n',char(10)),'sent','01a1b7f6-bb35-7a81-b501-3476036af443',NULL,'2026-11-07 21:42:42','2026-11-07 21:42:42');
