INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('12fe56a8-82ea-49f7-a56f-39dcbe30d3a3','87040095-5bc8-4c8d-be7c-13c134d62441','ed3271ff-c9ad-4ee9-ae5d-c74baf61c419',3,'followup_3','Hi Cooking Plumber Team,',replace('I noticed you''re the Director of \n\nFreedom Lifestyles🌍. I checked out your\nbrand''s website, and it made me want to\nask you a few quick questions.\n\n\n\nHave you ever got the feeling your site might\nbe leaking revenue right now?  Like maybe\nyou could be racking up more sales without\nspending more or excessively? \n\n\nOften, it’s just one or few hidden issues holding a\nsite back —  which is enough to block growth,\ndrain profits and eat into your revenue\nwithout you even knowing.🚧\n\n\n\nAnd the crazy part is, you might swear your\nsite’s all good — but then boom💥, you find out\nit could’ve been making you more this whole\ntime.\n\n\n\nYou see, I’ve been digging into this, and I\nfound some pretty powerful insights🔑 you’ll\nwant to see.\n\n\n\n\nBut before that, here is a quick intro of me:\n\n\n\nI’m Precious👋 — an eCommerce Virtual Assistant.\nI specialize in spotting where brands are\nbleeding profit… and fixing it fast⚡ to\nreduce expenses and increase their ROI.\n\n\n\n\nIn simple terms: I help online businesses\nboost their revenue📈 and cut unnecessary\nlosses, I use smarter systems, sharper\nstrategy, and updates that actually fix.\n\n\n\n\nSo, I’d love to share what I found. I believe\nthis could be the start of something\ngame-changing🚀 for your business.\n\n\n\n\n👉Are you open to a quick chat? If so, what\ntime works best for you? I can easily work\naround your schedule.\n\n\n\nAnd I''m also curious — what’s your local\ntime zone? ⏰Or does this message correspond\nwith your time zone?\n\n\nI’m asking so I won’t reach out during your busy\nor sleeping hours. I just wanna sync when the\ntiming’s right on your end.  And I''d be happy\nto roll on your clock\n\n\n\n\nThanks for your attention!\n\nPrecious','\n',char(10)),'sent','1a1b152774032ff7',NULL,NULL,NULL,NULL,'2026-11-06T14:45:31.960Z','2026-11-06T14:45:34.476Z');
